def get_aphelios_weapon_icon_url(weapon_id):
    return f"https://ddragon.leagueoflegends.com/cdn/16.17.1/img/spell/Aphelios{weapon_id}Q.png"

# 챔피언별 특징 & 공략 (직접 작성해주신 내용)
CHAMPION_GUIDES = {
    "드레이븐": """드레이븐은 우선 Q 회전도끼의 의존도가 매우 크다. 회전도끼가 활성화 되어있는지 안 되어있는지 유무에 따라 드레이븐의 대미지는 크게 나뉜다.

드레이븐은 Q 스킬을 활성화 한 뒤 상대방에게 평타를 때리면 드레이븐이 마지막으로 움직인 방향으로 도끼가 떨어지는데, 도끼가 떨어지는 곳에 서 있으면 도끼를 줍게 되고, Q 스킬 활성화 시간 갱신과 W가 쿨타임 일시 초기화 되고 패시브 스택이 1스택이 쌓인다.

Q는 총 2스택 활성화 할 수 있는데, Q를 2스택 활성화 한다면 중간 딜로스 없이 도끼만 계속 받아내면 강력한 평타를 때릴 수 있다.

드레이븐의 특징은 패시브에도 존재하는데, 앞서 설명한 도끼를 얻으면 패시브 1스택이 쌓인다.

드레이븐의 패시브는 적을 처치했을 때 패시브 스택만큼 골드를 얻게 되지만, 죽게 되면 패시브의 일정 스택이 사라진다.

그 외에 W는 이속과 공격 속도 증가, E는 약간의 CC기, 궁극기는 폭발적인 대미지를 넣을 수 있는 글로벌 궁이다.

그렇다면 드레이븐을 어떤 식으로 사용해야 할까?

우선 드레이븐의 Q가 2스택이 쌓였을 때 제일 강력하기 때문에 2스택이 쌓인 타이밍에 적극적인 딜교나 교전 각을 보면 된다.

드레이븐이 강한 타이밍은 1렙(Q 2스택), 2렙 (W 찍혔을 때), 6렙 (궁극기 찍혔을 때)이다. 아이템 트리는 주로 피바라기 > 징수의 총> 무한의 대검이다.""",
}


def get_champion_image(champ_name):
    """URL(str) 또는 로컬 이미지(bytes)를 반환. 없으면 None."""
    if champ_name in CHAMPION_IMAGE_BYTES_MAP:
        return CHAMPION_IMAGE_BYTES_MAP[champ_name]
    return CHAMPION_IMAGE_MAP.get(champ_name)


# 세션 상태 초기화
if "page" not in st.session_state:
    st.session_state.page = "intro"  # intro / list / detail
if "selected_champ" not in st.session_state:
    st.session_state.selected_champ = None


def enter_wiki():
    st.session_state.page = "list"


def go_to_detail(champ):
    st.session_state.selected_champ = champ
    st.session_state.page = "detail"


def back_to_list():
    st.session_state.selected_champ = None
    st.session_state.page = "list"


def back_to_intro():
    st.session_state.page = "intro"


# 1. 첫 화면
if st.session_state.page == "intro":
    st.markdown(
        "<h1 style='text-align: center; color: #FF4B4B;'>캐리를 하고 싶은 자들을 위한 위키</h1>",
        unsafe_allow_html=True,
    )
    st.markdown(
        "<h3 style='text-align: center;'>숟가락이라는 멸칭은 잊어라! 우리가 바로 게임의 주인공이다! 🥄✨</h3>",
        unsafe_allow_html=True,
    )
    st.write("---")

    col1, col2, col3 = st.columns([1, 1, 1])
    with col2:
        st.button(
            "들어가기 🚀 (클릭 시 마우스 우클릭 연타 준비)",
            on_click=enter_wiki,
            use_container_width=True,
        )

# 2. 챔피언 목록 화면
elif st.session_state.page == "list":
    st.title("원거리 딜러 챔피언 도감 🎯")
    st.write("가나다 순으로 예쁘게 정렬해 놨어. 이제 카이팅 연습만 남았다!")
    st.write("---")

    champions = [
        "드레이븐", "유나라", "미스 포츈", "이즈리얼", "카이사",
        "아펠리오스", "자야", "코르키", "케이틀린", "루시안",
        "칼리스타", "애쉬", "코그모", "진", "제리",
        "징크스", "바루스", "시비르",
    ]
    sorted_champs = sorted(champions)

    # 초상화 + 버튼을 3열 그리드로 배치
    cols_per_row = 3
    for i in range(0, len(sorted_champs), cols_per_row):
        row_champs = sorted_champs[i : i + cols_per_row]
        row_cols = st.columns(cols_per_row)
        for col, champ in zip(row_cols, row_champs):
            with col:
                img_url = get_champion_image(champ)
                if img_url:
                    st.image(img_url, use_container_width=True)
                else:
                    st.markdown(
                        "<div style='height:80px; display:flex; align-items:center; "
                        "justify-content:center; background:#333; border-radius:8px; "
                        "color:white;'>🎯</div>",
                        unsafe_allow_html=True,
                    )
                st.button(
                    champ,
                    key=f"btn_{champ}",
                    on_click=go_to_detail,
                    args=(champ,),
                    use_container_width=True,
                )

    st.write("---")
    st.button("⬅️ 뒤로 가기 (우물로 귀환)", on_click=back_to_intro)

# 3. 챔피언 상세 화면
elif st.session_state.page == "detail":
    champ = st.session_state.selected_champ
    img_url = get_champion_image(champ)

    col1, col2 = st.columns([1, 3])
    with col1:
        if img_url:
            st.image(img_url, use_container_width=True)
    with col2:
        st.title(champ)

    # 스킬 (Q/W/E/R) - 챔피언 이름 바로 아래에 배치
    champ_id = CHAMPION_ID_MAP.get(champ)
    skills = CHAMPION_SKILLS.get(champ)
    if skills and champ_id:
        skill_cols = st.columns(4)
        for slot, col in zip(["Q", "W", "E", "R"], skill_cols):
            skill_name, skill_desc = skills[slot]
            with col:
                st.image(get_ability_icon_url(champ_id, slot.lower()), width=64)
                st.markdown(f"**{slot} · {skill_name}**")
                st.caption(skill_desc)
    else:
        st.info("스킬 정보는 아직 준비 중이에요. 🚧")

    st.write("---")
    st.subheader("특징 & 공략")
    guide = CHAMPION_GUIDES.get(champ)
    if champ == "아펠리오스":
        st.write("아펠리오스는 5가지 무기를 아래 순서로 돌려 씁니다.")
        for weapon_id, weapon_name, weapon_desc in APHELIOS_WEAPONS:
            w_col1, w_col2 = st.columns([1, 4])
            with w_col1:
                st.image(get_aphelios_weapon_icon_url(weapon_id), width=64)
            with w_col2:
                st.markdown(f"**{weapon_name}**")
                st.caption(weapon_desc)
    elif guide:
        st.markdown(guide)
    else:
        st.write(
            f"여기에 **{champ}**의 카이팅 비법과 서포터에게 핑 찍는(?) 노하우를 "
            "적을 예정입니다. (현재 공사 중 🚧)"
        )

    st.write("---")
    st.button("⬅️ 목록으로 돌아가기", on_click=back_to_list)
